<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'; import { useRoute } from 'vue-router'; import { Save, ChevronLeft, ShieldCheck } from 'lucide-vue-next'; import { api,post,put } from '../api'; import { router } from '../main'; import { PageHeader } from '../components/Common.vue'
const route=useRoute(),editing=computed(()=>!!route.params.id),saving=ref(false),error=ref(''); const form=reactive<any>({slug:'',name:'',description:'',isEnabled:true,svnUrl:'',svnUserName:'',svnPassword:'',trustServerCertificate:false,trunkPath:'05-trunk',backendDirectory:'05-trunk/webapi/iHR.Hosting',backendProjectFile:'iHR.Hosting.csproj',entryAssembly:'iHR.Hosting.dll',adminDirectory:'05-trunk/webui/admin',terminalDirectory:'05-trunk/webui/terminal',adminBuildCommand:'npm run build',terminalBuildCommand:'npm run build',adminOutputDirectory:'dist',terminalOutputDirectory:'dist',buildConfiguration:'Release',targetFramework:'net8.0',environmentVariablesJson:'{}',startArgumentsJson:'[]',healthCheckUrl:'',healthExpectedStatus:200,healthTimeoutSeconds:10,stopTimeoutSeconds:15,buildTimeoutMinutes:30,retainReleaseCount:3,retainPackageDays:30})
onMounted(async()=>{if(editing.value)Object.assign(form,await api(`/projects/${route.params.id}`),{svnPassword:''})});async function save(){saving.value=true;error.value='';try{const r:any=editing.value?await put(`/projects/${route.params.id}`,form):await post('/projects',form);router.push(`/projects/${r.id}/overview`)}catch(e:any){error.value=e.message}finally{saving.value=false}}
</script>
<template><PageHeader eyebrow="PROJECT CONFIGURATION" :title="editing?'编辑项目':'创建项目'" description="路径均相对于隔离工作区，平台不会接受绝对输出目录。"><button class="btn ghost" @click="router.back()"><ChevronLeft :size="16"/>返回</button><button class="btn primary" @click="save" :disabled="saving"><Save :size="16"/>{{saving?'保存中…':'保存项目'}}</button></PageHeader><div v-if="error" class="alert error">{{error}}</div><form class="editor-layout" @submit.prevent="save"><section class="form-card"><div class="section-title"><span>01</span><div><h3>项目身份</h3><p>用于区分工作区、版本目录和压缩包。</p></div></div><div class="form-grid"><label>项目名称<input v-model="form.name" required/></label><label>唯一标识<input v-model="form.slug" pattern="[a-z0-9][a-z0-9-]+" required :disabled="editing"/></label><label class="span-2">项目说明<textarea v-model="form.description" rows="2"/></label><label class="switch"><input v-model="form.isEnabled" type="checkbox"/><span></span>启用项目</label></div></section><section class="form-card"><div class="section-title"><span>02</span><div><h3>SVN 源码</h3><p>密码使用平台 Data Protection 密钥加密保存。</p></div><ShieldCheck class="section-icon"/></div><div class="form-grid"><label class="span-2">仓库地址<input v-model="form.svnUrl" placeholder="https://server/svn/project" required/></label><label>用户名<input v-model="form.svnUserName" required/></label><label>密码<input v-model="form.svnPassword" type="password" :placeholder="editing?'留空表示不修改':'输入 SVN 密码'"/></label><label>主干相对路径<input v-model="form.trunkPath" required/></label><label class="switch"><input v-model="form.trustServerCertificate" type="checkbox"/><span></span>信任指定证书异常</label></div></section><section class="form-card"><div class="section-title"><span>03</span><div><h3>构建坐标</h3><p>.NET 后台与两个 Vue 前端的标准目录。</p></div></div><div class="form-grid"><label>后台目录<input v-model="form.backendDirectory"/></label><label>项目文件<input v-model="form.backendProjectFile"/></label><label>入口程序集<input v-model="form.entryAssembly"/></label><label>目标框架<input v-model="form.targetFramework"/></label><label>admin 目录<input v-model="form.adminDirectory"/></label><label>admin 输出<input v-model="form.adminOutputDirectory"/></label><label>terminal 目录<input v-model="form.terminalDirectory"/></label><label>terminal 输出<input v-model="form.terminalOutputDirectory"/></label></div></section><section class="form-card"><div class="section-title"><span>04</span><div><h3>运行与保留</h3><p>配置超时、健康检查和版本治理策略。</p></div></div><div class="form-grid"><label class="span-2">健康检查地址<input v-model="form.healthCheckUrl" placeholder="可选，如 http://localhost:5000/health"/></label><label>构建超时（分钟）<input v-model.number="form.buildTimeoutMinutes" type="number" min="1"/></label><label>停止超时（秒）<input v-model.number="form.stopTimeoutSeconds" type="number" min="1"/></label><label>保留成功版本<input v-model.number="form.retainReleaseCount" type="number" min="3"/></label><label>发布包保留天数<input v-model.number="form.retainPackageDays" type="number" min="1"/></label><label class="span-2">环境变量 JSON<textarea v-model="form.environmentVariablesJson" class="code" rows="4"/></label><label class="span-2">启动参数 JSON 数组<textarea v-model="form.startArgumentsJson" class="code" rows="3"/></label></div></section></form></template>
